CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity and the name shown in the audit trail.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name on rule authorship and approvals.
	"full_name" VARCHAR(160) NOT NULL,
	-- False when someone leaves. Never deleted, because every audit row points here.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person who can change flag configuration. Deactivation rather than deletion keeps the audit log readable years later.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity and the name shown in the audit trail.';
COMMENT ON COLUMN "users"."full_name" IS 'Display name on rule authorship and approvals.';
COMMENT ON COLUMN "users"."is_active" IS 'False when someone leaves. Never deleted, because every audit row points here.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "projects" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- URL-safe identifier used in SDK config and API paths.
	"key" VARCHAR(60) NOT NULL UNIQUE,
	-- Human name shown in the dashboard.
	"name" VARCHAR(160) NOT NULL,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "projects" IS 'The namespace a flag key is unique within. One product or one service per project, so two teams can both own a flag called new-checkout.';
COMMENT ON COLUMN "projects"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "projects"."key" IS 'URL-safe identifier used in SDK config and API paths.';
COMMENT ON COLUMN "projects"."name" IS 'Human name shown in the dashboard.';
COMMENT ON COLUMN "projects"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "environments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Short identifier such as production or staging.
	"key" VARCHAR(60) NOT NULL,
	-- Display name.
	"name" VARCHAR(120) NOT NULL,
	-- Hash of the SDK key an application presents. The plaintext key is shown once at creation and never stored, so a database leak does not hand over the ability to read production config.
	"sdk_key_hash" VARCHAR(255) NOT NULL UNIQUE,
	-- Marks environments that need approval before a change lands. Drives the scheduled-change and audit workflow, not evaluation.
	"is_production" BOOLEAN NOT NULL DEFAULT false,
	-- When true, a change is written as a scheduled change with a reviewer instead of applied directly.
	"requires_approval" BOOLEAN NOT NULL DEFAULT false,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "environments" IS 'An independent copy of every flag configuration. The flag definition is shared across environments; everything that decides what a user actually sees is per environment, which is what lets a flag be on in staging and off in production.';
COMMENT ON COLUMN "environments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "environments"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "environments"."key" IS 'Short identifier such as production or staging.';
COMMENT ON COLUMN "environments"."name" IS 'Display name.';
COMMENT ON COLUMN "environments"."sdk_key_hash" IS 'Hash of the SDK key an application presents. The plaintext key is shown once at creation and never stored, so a database leak does not hand over the ability to read production config.';
COMMENT ON COLUMN "environments"."is_production" IS 'Marks environments that need approval before a change lands. Drives the scheduled-change and audit workflow, not evaluation.';
COMMENT ON COLUMN "environments"."requires_approval" IS 'When true, a change is written as a scheduled change with a reviewer instead of applied directly.';
COMMENT ON COLUMN "environments"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_environments_project_key"
ON "environments" ("project_id", "key");

CREATE TABLE IF NOT EXISTS "flags" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- The string an SDK call passes. Immutable once created, because it is compiled into application source.
	"key" VARCHAR(120) NOT NULL,
	-- Readable title for the dashboard.
	"name" VARCHAR(160) NOT NULL,
	-- What the flag controls and when it can be removed.
	"description" TEXT,
	-- boolean | string | number | json. Decides how the variation payload is interpreted by the SDK.
	"kind" VARCHAR(16) NOT NULL DEFAULT 'boolean',
	-- True for kill switches and entitlement flags that are never meant to be removed. Everything else shows up in stale-flag reports.
	"is_permanent" BOOLEAN NOT NULL DEFAULT false,
	-- Soft removal. An archived flag stops being served but its evaluation history and audit rows stay queryable.
	"archived_at" TIMESTAMPTZ,
	-- Author. Null once the account is hard deleted.
	"created_by_id" BIGINT,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "flags" IS 'The flag definition, shared by every environment. Nothing here says whether the flag is on, because on-ness is a per-environment property.';
COMMENT ON COLUMN "flags"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "flags"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "flags"."key" IS 'The string an SDK call passes. Immutable once created, because it is compiled into application source.';
COMMENT ON COLUMN "flags"."name" IS 'Readable title for the dashboard.';
COMMENT ON COLUMN "flags"."description" IS 'What the flag controls and when it can be removed.';
COMMENT ON COLUMN "flags"."kind" IS 'boolean | string | number | json. Decides how the variation payload is interpreted by the SDK.';
COMMENT ON COLUMN "flags"."is_permanent" IS 'True for kill switches and entitlement flags that are never meant to be removed. Everything else shows up in stale-flag reports.';
COMMENT ON COLUMN "flags"."archived_at" IS 'Soft removal. An archived flag stops being served but its evaluation history and audit rows stay queryable.';
COMMENT ON COLUMN "flags"."created_by_id" IS 'Author. Null once the account is hard deleted.';
COMMENT ON COLUMN "flags"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_flags_project_key"
ON "flags" ("project_id", "key");

CREATE TABLE IF NOT EXISTS "flag_variations" (
	-- Surrogate primary key referenced by rules and rollouts.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning flag.
	"flag_id" BIGINT NOT NULL,
	-- Stable identifier such as control or treatment. Referenced by experiment analysis, so it outlives renames of the display name.
	"key" VARCHAR(60) NOT NULL,
	-- Display name in the dashboard.
	"name" VARCHAR(120) NOT NULL,
	-- The payload served for this variation. JSON for every flag kind so a boolean flag and a config flag share one code path.
	"value_json" JSONB NOT NULL,
	-- Display order. Variation 0 is conventionally the off or control value.
	"ordinal" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "flag_variations" IS 'The closed set of values a flag may serve. Rules point at variations rather than carrying literal values, so renaming a payload is one update instead of a sweep through every rule.';
COMMENT ON COLUMN "flag_variations"."id" IS 'Surrogate primary key referenced by rules and rollouts.';
COMMENT ON COLUMN "flag_variations"."flag_id" IS 'Owning flag.';
COMMENT ON COLUMN "flag_variations"."key" IS 'Stable identifier such as control or treatment. Referenced by experiment analysis, so it outlives renames of the display name.';
COMMENT ON COLUMN "flag_variations"."name" IS 'Display name in the dashboard.';
COMMENT ON COLUMN "flag_variations"."value_json" IS 'The payload served for this variation. JSON for every flag kind so a boolean flag and a config flag share one code path.';
COMMENT ON COLUMN "flag_variations"."ordinal" IS 'Display order. Variation 0 is conventionally the off or control value.';

CREATE UNIQUE INDEX "uq_flag_variations_flag_key"
ON "flag_variations" ("flag_id", "key");

CREATE TABLE IF NOT EXISTS "flag_environment_settings" (
	-- Surrogate primary key. Rules and scheduled changes hang off this rather than off a flag and environment pair.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Flag being configured.
	"flag_id" BIGINT NOT NULL,
	-- Environment the configuration applies to.
	"environment_id" BIGINT NOT NULL,
	-- The kill switch. False short-circuits every rule and serves off_variation_id, which is what makes turning a flag off a single-row write.
	"is_enabled" BOOLEAN NOT NULL DEFAULT false,
	-- Fallthrough variation served when the flag is enabled and no rule matched. Null when the fallthrough is a percentage rollout, which is stored as a final rule with no clauses.
	"on_variation_id" BIGINT,
	-- Variation served when is_enabled is false. Explicit rather than implied, because the safe value for a kill switch is not always the first variation.
	"off_variation_id" BIGINT,
	-- Random salt mixed into the bucketing hash. Changing it reshuffles every user across the rollout, which is exactly what you want when re-randomising an experiment and exactly what you must not do mid-flight.
	"bucket_salt" VARCHAR(64) NOT NULL,
	-- Incremented on every change. SDKs send it back so the server can tell a stale poll from a fresh one, and evaluation events record which version produced them.
	"version" INTEGER NOT NULL DEFAULT 1,
	-- Who last changed the configuration.
	"updated_by_id" BIGINT,
	-- Last change time. Drives the flag-changed feed.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "flag_environment_settings" IS 'One row per flag per environment, and the thing the SDK actually downloads. Every knob that changes behaviour lives here, so a rollback is a single row restored from the audit log.';
COMMENT ON COLUMN "flag_environment_settings"."id" IS 'Surrogate primary key. Rules and scheduled changes hang off this rather than off a flag and environment pair.';
COMMENT ON COLUMN "flag_environment_settings"."flag_id" IS 'Flag being configured.';
COMMENT ON COLUMN "flag_environment_settings"."environment_id" IS 'Environment the configuration applies to.';
COMMENT ON COLUMN "flag_environment_settings"."is_enabled" IS 'The kill switch. False short-circuits every rule and serves off_variation_id, which is what makes turning a flag off a single-row write.';
COMMENT ON COLUMN "flag_environment_settings"."on_variation_id" IS 'Fallthrough variation served when the flag is enabled and no rule matched. Null when the fallthrough is a percentage rollout, which is stored as a final rule with no clauses.';
COMMENT ON COLUMN "flag_environment_settings"."off_variation_id" IS 'Variation served when is_enabled is false. Explicit rather than implied, because the safe value for a kill switch is not always the first variation.';
COMMENT ON COLUMN "flag_environment_settings"."bucket_salt" IS 'Random salt mixed into the bucketing hash. Changing it reshuffles every user across the rollout, which is exactly what you want when re-randomising an experiment and exactly what you must not do mid-flight.';
COMMENT ON COLUMN "flag_environment_settings"."version" IS 'Incremented on every change. SDKs send it back so the server can tell a stale poll from a fresh one, and evaluation events record which version produced them.';
COMMENT ON COLUMN "flag_environment_settings"."updated_by_id" IS 'Who last changed the configuration.';
COMMENT ON COLUMN "flag_environment_settings"."updated_at" IS 'Last change time. Drives the flag-changed feed.';

CREATE UNIQUE INDEX "uq_flag_env_settings"
ON "flag_environment_settings" ("flag_id", "environment_id");
CREATE INDEX "idx_flag_env_settings_env_updated"
ON "flag_environment_settings" ("environment_id", "updated_at");

CREATE TABLE IF NOT EXISTS "segments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Identifier used in rules and in the SDK payload.
	"key" VARCHAR(120) NOT NULL,
	-- Display name such as Beta testers or EU enterprise accounts.
	"name" VARCHAR(160) NOT NULL,
	-- Who is in the segment and why it exists.
	"description" TEXT,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "segments" IS 'A reusable named audience, defined by the same clause language rules use. Extracting it means the definition of beta tester is fixed once instead of copied into fourteen rules that slowly drift apart.';
COMMENT ON COLUMN "segments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "segments"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "segments"."key" IS 'Identifier used in rules and in the SDK payload.';
COMMENT ON COLUMN "segments"."name" IS 'Display name such as Beta testers or EU enterprise accounts.';
COMMENT ON COLUMN "segments"."description" IS 'Who is in the segment and why it exists.';
COMMENT ON COLUMN "segments"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_segments_project_key"
ON "segments" ("project_id", "key");

CREATE TABLE IF NOT EXISTS "targeting_rules" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The flag and environment pair this rule belongs to. Hanging off the settings row rather than off flag plus environment makes it impossible to write a rule for a combination that was never configured.
	"setting_id" BIGINT NOT NULL,
	-- Evaluation order, lowest first. The first matching rule wins and evaluation stops, so order is behaviour, not presentation.
	"ordinal" SMALLINT NOT NULL,
	-- What the rule is for, shown in the dashboard and copied into audit entries.
	"description" VARCHAR(255),
	-- When set, the rule matches if the context is in this segment. Mutually exclusive in practice with inline clauses, which cover the one-off cases.
	"segment_id" BIGINT,
	-- Variation served on a match. Null means the rule serves a percentage rollout, defined in rule_rollouts.
	"variation_id" BIGINT,
	-- Context attribute hashed for a rollout. Bucketing by account_id instead of user id is how every user in a company sees the same variant.
	"bucket_by" VARCHAR(120) NOT NULL DEFAULT 'key',
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "targeting_rules" IS 'An ordered if-clause in the evaluation of one flag in one environment. A rule either serves a fixed variation or a weighted rollout; a final rule with no clauses is how a percentage fallthrough is expressed.';
COMMENT ON COLUMN "targeting_rules"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "targeting_rules"."setting_id" IS 'The flag and environment pair this rule belongs to. Hanging off the settings row rather than off flag plus environment makes it impossible to write a rule for a combination that was never configured.';
COMMENT ON COLUMN "targeting_rules"."ordinal" IS 'Evaluation order, lowest first. The first matching rule wins and evaluation stops, so order is behaviour, not presentation.';
COMMENT ON COLUMN "targeting_rules"."description" IS 'What the rule is for, shown in the dashboard and copied into audit entries.';
COMMENT ON COLUMN "targeting_rules"."segment_id" IS 'When set, the rule matches if the context is in this segment. Mutually exclusive in practice with inline clauses, which cover the one-off cases.';
COMMENT ON COLUMN "targeting_rules"."variation_id" IS 'Variation served on a match. Null means the rule serves a percentage rollout, defined in rule_rollouts.';
COMMENT ON COLUMN "targeting_rules"."bucket_by" IS 'Context attribute hashed for a rollout. Bucketing by account_id instead of user id is how every user in a company sees the same variant.';
COMMENT ON COLUMN "targeting_rules"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_targeting_rules_setting_ordinal"
ON "targeting_rules" ("setting_id", "ordinal");

CREATE TABLE IF NOT EXISTS "clauses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning targeting rule. Exactly one of rule_id and segment_id is set.
	"rule_id" BIGINT,
	-- Owning segment. Exactly one of rule_id and segment_id is set.
	"segment_id" BIGINT,
	-- Display order only. Clauses within an owner are ANDed, so unlike rules the order does not change the outcome.
	"ordinal" SMALLINT NOT NULL DEFAULT 0,
	-- Context attribute read from the evaluation payload, such as email, country or plan_tier.
	"attribute" VARCHAR(120) NOT NULL,
	-- in | not_in | starts_with | ends_with | contains | matches | greater_than | less_than | before | after | semver_gte. The vocabulary is fixed because every SDK has to implement it identically.
	"operator" VARCHAR(24) NOT NULL,
	-- Array of comparison operands. An array even for single-value operators, so the SDK has one comparison loop instead of two shapes to handle.
	"values_json" JSONB NOT NULL,
	-- Inverts the match. Cheaper than doubling the operator vocabulary with a not_ variant of each.
	"negate" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "clauses" IS 'One condition, shared by targeting rules and segment definitions. Two identical clause tables would guarantee the two implementations drift; one table with a nullable owner pair means a segment and a rule are evaluated by exactly the same code.';
COMMENT ON COLUMN "clauses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "clauses"."rule_id" IS 'Owning targeting rule. Exactly one of rule_id and segment_id is set.';
COMMENT ON COLUMN "clauses"."segment_id" IS 'Owning segment. Exactly one of rule_id and segment_id is set.';
COMMENT ON COLUMN "clauses"."ordinal" IS 'Display order only. Clauses within an owner are ANDed, so unlike rules the order does not change the outcome.';
COMMENT ON COLUMN "clauses"."attribute" IS 'Context attribute read from the evaluation payload, such as email, country or plan_tier.';
COMMENT ON COLUMN "clauses"."operator" IS 'in | not_in | starts_with | ends_with | contains | matches | greater_than | less_than | before | after | semver_gte. The vocabulary is fixed because every SDK has to implement it identically.';
COMMENT ON COLUMN "clauses"."values_json" IS 'Array of comparison operands. An array even for single-value operators, so the SDK has one comparison loop instead of two shapes to handle.';
COMMENT ON COLUMN "clauses"."negate" IS 'Inverts the match. Cheaper than doubling the operator vocabulary with a not_ variant of each.';

CREATE INDEX "idx_clauses_rule"
ON "clauses" ("rule_id");
CREATE INDEX "idx_clauses_segment"
ON "clauses" ("segment_id");

CREATE TABLE IF NOT EXISTS "rule_rollouts" (
	-- Rule the rollout belongs to. Half of the composite primary key.
	"rule_id" BIGINT,
	-- Variation receiving a share of traffic. The other half of the key, which makes a duplicate weight for one variation impossible.
	"variation_id" BIGINT,
	-- Share of traffic in basis points. Integers summing to 10000 let a 0.05% canary be expressed exactly, which percentages stored as floats cannot.
	"weight_bps" INTEGER NOT NULL,
	PRIMARY KEY("rule_id", "variation_id")
);

COMMENT ON TABLE "rule_rollouts" IS 'The weights of a percentage rollout. Cumulative sums of these buckets are compared against the hash of the bucketing attribute, so a user lands in the same slice on every evaluation without the server remembering anything.';
COMMENT ON COLUMN "rule_rollouts"."rule_id" IS 'Rule the rollout belongs to. Half of the composite primary key.';
COMMENT ON COLUMN "rule_rollouts"."variation_id" IS 'Variation receiving a share of traffic. The other half of the key, which makes a duplicate weight for one variation impossible.';
COMMENT ON COLUMN "rule_rollouts"."weight_bps" IS 'Share of traffic in basis points. Integers summing to 10000 let a 0.05% canary be expressed exactly, which percentages stored as floats cannot.';

CREATE TABLE IF NOT EXISTS "scheduled_changes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Configuration the change will be applied to.
	"setting_id" BIGINT NOT NULL,
	-- When the worker should apply it. A row scheduled in the past is applied on the next sweep rather than skipped.
	"scheduled_for" TIMESTAMPTZ NOT NULL,
	-- The patch to apply, expressed as the same shape the API accepts. Storing intent rather than a full snapshot lets two queued changes to different fields both land.
	"change_json" JSONB NOT NULL,
	-- pending | applied | cancelled | failed. Terminal states are kept rather than deleted so an unexpected midnight change has an explanation.
	"state" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Reviewer, for environments that require approval. Null while the change is still awaiting review.
	"approved_by_id" BIGINT,
	-- When the worker committed it. Compared against scheduled_for to surface a lagging scheduler.
	"applied_at" TIMESTAMPTZ,
	-- Why it failed, typically a variation that was deleted between scheduling and execution.
	"failure_reason" VARCHAR(500),
	-- Who scheduled it.
	"created_by_id" BIGINT,
	-- When it was queued.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "scheduled_changes" IS 'A configuration change queued for later: a ramp step, a timed kill, a launch at a press embargo. The due index is the whole query the scheduler runs, so the sweep stays cheap no matter how much history accumulates.';
COMMENT ON COLUMN "scheduled_changes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "scheduled_changes"."setting_id" IS 'Configuration the change will be applied to.';
COMMENT ON COLUMN "scheduled_changes"."scheduled_for" IS 'When the worker should apply it. A row scheduled in the past is applied on the next sweep rather than skipped.';
COMMENT ON COLUMN "scheduled_changes"."change_json" IS 'The patch to apply, expressed as the same shape the API accepts. Storing intent rather than a full snapshot lets two queued changes to different fields both land.';
COMMENT ON COLUMN "scheduled_changes"."state" IS 'pending | applied | cancelled | failed. Terminal states are kept rather than deleted so an unexpected midnight change has an explanation.';
COMMENT ON COLUMN "scheduled_changes"."approved_by_id" IS 'Reviewer, for environments that require approval. Null while the change is still awaiting review.';
COMMENT ON COLUMN "scheduled_changes"."applied_at" IS 'When the worker committed it. Compared against scheduled_for to surface a lagging scheduler.';
COMMENT ON COLUMN "scheduled_changes"."failure_reason" IS 'Why it failed, typically a variation that was deleted between scheduling and execution.';
COMMENT ON COLUMN "scheduled_changes"."created_by_id" IS 'Who scheduled it.';
COMMENT ON COLUMN "scheduled_changes"."created_at" IS 'When it was queued.';

CREATE INDEX "idx_scheduled_changes_due"
ON "scheduled_changes" ("state", "scheduled_for");
CREATE INDEX "idx_scheduled_changes_setting"
ON "scheduled_changes" ("setting_id");

CREATE TABLE IF NOT EXISTS "evaluation_events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Flag that was evaluated.
	"flag_id" BIGINT NOT NULL,
	-- Environment the evaluation happened in.
	"environment_id" BIGINT NOT NULL,
	-- Variation served. Null when evaluation errored and the SDK fell back to the code default, which is the case worth alerting on.
	"variation_id" BIGINT,
	-- Rule that matched. Null for a fallthrough, a kill-switch serve or an error.
	"rule_id" BIGINT,
	-- The identifier the context was keyed by. Hashed or pseudonymous in most deployments, since this table is the highest-volume one here.
	"context_key" VARCHAR(255) NOT NULL,
	-- off | target_match | rule_match | fallthrough | error. Recording why a value was served is what turns support tickets from guesswork into a lookup.
	"reason" VARCHAR(24) NOT NULL,
	-- Version of flag_environment_settings that produced the result, so a stale SDK poll is distinguishable from a wrong rule.
	"settings_version" INTEGER NOT NULL,
	-- How many real evaluations this row stands for. Clients send one in N; multiplying by the weight recovers true counts without storing every hit.
	"sample_weight" INTEGER NOT NULL DEFAULT 1,
	-- Client-reported evaluation time, not receipt time, so batching does not distort the timeline.
	"evaluated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "evaluation_events" IS 'Sampled record of what was served to whom and why. It answers the two questions a flag system is always asked: is this flag still used, and why did that customer see the old checkout.';
COMMENT ON COLUMN "evaluation_events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "evaluation_events"."flag_id" IS 'Flag that was evaluated.';
COMMENT ON COLUMN "evaluation_events"."environment_id" IS 'Environment the evaluation happened in.';
COMMENT ON COLUMN "evaluation_events"."variation_id" IS 'Variation served. Null when evaluation errored and the SDK fell back to the code default, which is the case worth alerting on.';
COMMENT ON COLUMN "evaluation_events"."rule_id" IS 'Rule that matched. Null for a fallthrough, a kill-switch serve or an error.';
COMMENT ON COLUMN "evaluation_events"."context_key" IS 'The identifier the context was keyed by. Hashed or pseudonymous in most deployments, since this table is the highest-volume one here.';
COMMENT ON COLUMN "evaluation_events"."reason" IS 'off | target_match | rule_match | fallthrough | error. Recording why a value was served is what turns support tickets from guesswork into a lookup.';
COMMENT ON COLUMN "evaluation_events"."settings_version" IS 'Version of flag_environment_settings that produced the result, so a stale SDK poll is distinguishable from a wrong rule.';
COMMENT ON COLUMN "evaluation_events"."sample_weight" IS 'How many real evaluations this row stands for. Clients send one in N; multiplying by the weight recovers true counts without storing every hit.';
COMMENT ON COLUMN "evaluation_events"."evaluated_at" IS 'Client-reported evaluation time, not receipt time, so batching does not distort the timeline.';

CREATE INDEX "idx_eval_events_flag_env_time"
ON "evaluation_events" ("flag_id", "environment_id", "evaluated_at");
CREATE INDEX "idx_eval_events_env_time"
ON "evaluation_events" ("environment_id", "evaluated_at");

CREATE TABLE IF NOT EXISTS "flag_audit_log" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Flag that changed.
	"flag_id" BIGINT NOT NULL,
	-- Environment affected. Null for changes to the flag definition itself, which apply everywhere.
	"environment_id" BIGINT,
	-- Who made the change. Null for changes applied by the scheduler or by an API token.
	"actor_id" BIGINT,
	-- user | api_token | scheduler. Without it an automated ramp is indistinguishable from a human at 3am.
	"actor_kind" VARCHAR(16) NOT NULL DEFAULT 'user',
	-- flag_created | rule_added | rule_reordered | rollout_changed | toggled_on | toggled_off | archived and so on.
	"action" VARCHAR(40) NOT NULL,
	-- Configuration before the change. Null on creation.
	"before_state" JSONB,
	-- Configuration after the change. Null on deletion. Keeping both sides makes a one-click revert a write of before_state rather than a replay of history.
	"after_state" JSONB,
	-- Optional reason supplied by the author, required in environments that gate changes on approval.
	"comment" VARCHAR(500),
	-- When the change landed.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "flag_audit_log" IS 'Append-only history of every configuration change. A flag system is a remote control for production, so the question after an incident is always who moved what, and this table is the only acceptable answer.';
COMMENT ON COLUMN "flag_audit_log"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "flag_audit_log"."flag_id" IS 'Flag that changed.';
COMMENT ON COLUMN "flag_audit_log"."environment_id" IS 'Environment affected. Null for changes to the flag definition itself, which apply everywhere.';
COMMENT ON COLUMN "flag_audit_log"."actor_id" IS 'Who made the change. Null for changes applied by the scheduler or by an API token.';
COMMENT ON COLUMN "flag_audit_log"."actor_kind" IS 'user | api_token | scheduler. Without it an automated ramp is indistinguishable from a human at 3am.';
COMMENT ON COLUMN "flag_audit_log"."action" IS 'flag_created | rule_added | rule_reordered | rollout_changed | toggled_on | toggled_off | archived and so on.';
COMMENT ON COLUMN "flag_audit_log"."before_state" IS 'Configuration before the change. Null on creation.';
COMMENT ON COLUMN "flag_audit_log"."after_state" IS 'Configuration after the change. Null on deletion. Keeping both sides makes a one-click revert a write of before_state rather than a replay of history.';
COMMENT ON COLUMN "flag_audit_log"."comment" IS 'Optional reason supplied by the author, required in environments that gate changes on approval.';
COMMENT ON COLUMN "flag_audit_log"."created_at" IS 'When the change landed.';

CREATE INDEX "idx_flag_audit_flag_time"
ON "flag_audit_log" ("flag_id", "created_at");
CREATE INDEX "idx_flag_audit_actor_time"
ON "flag_audit_log" ("actor_id", "created_at");

